function chatReply(question){const q=(question||'').toLowerCase(),offers=products.filter(p=>p.oldPrice).map(p=>p.name).join(', ');if(/oferta|descuento|rebaja|sale/.test(q))return `Las ofertas activas son: ${offers}. Puedes abrir “Ofertas” para verlas en el catálogo.`;if(/talla|medida|size/.test(q))return 'Cada ficha muestra las tallas disponibles. Selecciona tu talla antes de agregar al carro; los accesorios normalmente usan talla única.';if(/env[ií]o|despacho|entrega/.test(q))return 'El envío es demostrativo: es gratis sobre US$75 y, bajo ese monto, se agregan US$8 en el checkout demo.';if(/cambio|devoluci|garant/.test(q))return 'Los cambios son informativos en este prototipo. En una tienda real se indicarían plazo, estado del producto y comprobante de compra.';if(/carro|bolsa|comprar|pago|checkout|tarjeta/.test(q))return 'Usa el botón “Bolsa” para revisar cantidades. El checkout valida datos ficticios y crea un pedido demo; no realiza cobros.';if(/favorito|guardar/.test(q))return 'Pulsa el corazón de cualquier producto para guardarlo. Los favoritos se conservan en este navegador.';if(/producto|poler|gorro|cat[aá]logo|recomienda/.test(q))return `Tenemos ${products.length} productos demo. Para comenzar, revisa Polerón Field Classic, Gorro Gold Line o las ofertas de la sección catálogo.`;if(/hola|buenas|ayuda/.test(q))return '¡Hola! Pregúntame por productos, tallas, ofertas, envío, cambios, favoritos, bolsa o pago demo.';return 'Puedo orientarte sobre esta tienda demo: productos, tallas, precios, ofertas, favoritos, bolsa, checkout, envíos y cambios. Prueba preguntarme por uno de esos temas.'}
