const LOCAL_AUTH_KEY='gbps-local-accounts-v1',LOCAL_ADMIN_EMAIL='admin@packers.local',LOCAL_ADMIN_PASSWORD='GoPackers!2026';async function localPasswordHash(value){const bytes=new TextEncoder().encode(value),digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')}async function localAccounts(){let accounts=JSON.parse(localStorage.getItem(LOCAL_AUTH_KEY)||'[]');if(!accounts.length){accounts=[{name:'Administrador local',email:LOCAL_ADMIN_EMAIL,passwordHash:await localPasswordHash(LOCAL_ADMIN_PASSWORD),role:'admin',createdAt:new Date().toISOString()}];localStorage.setItem(LOCAL_AUTH_KEY,JSON.stringify(accounts))}return accounts}async function showAuth(mode='login'){if(!$('#authDialog'))document.body.insertAdjacentHTML('beforeend','<dialog id="authDialog" class="dialog auth-dialog"><button class="close" data-close="auth">×</button><div id="authContent"></div></dialog>');const register=mode==='register';$('#authContent').innerHTML=`<div class="auth-content"><p class="eyebrow">ACCESO LOCAL DEL DISPOSITIVO</p><h2>${register?'Crear cuenta demo':'Inicia sesión demo'}</h2><p>Las cuentas se guardan sólo en este navegador. No se envían a ningún servidor.</p><form id="authForm" class="checkout-form">${register?'<label>Nombre<input name="name" required minlength="3" placeholder="Tu nombre"></label>':''}<label>Correo<input name="email" type="email" required placeholder="tu@correo.com"></label><label>Contraseña<input name="password" type="password" required minlength="6" placeholder="Mínimo 6 caracteres"></label><button class="button button-gold">${register?'Crear cuenta local':'Entrar'}</button></form><button id="authSwitch" class="text-button">${register?'Ya tengo cuenta':'Crear una cuenta demo'}</button><small class="local-credential-note">Cuenta inicial local: ${LOCAL_ADMIN_EMAIL}</small></div>`;$('#authDialog').showModal();$('#authSwitch').addEventListener('click',()=>showAuth(register?'login':'register'));$('#authForm').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget),email=String(form.get('email')).trim().toLowerCase(),passwordHash=await localPasswordHash(String(form.get('password'))),accounts=await localAccounts(),existing=accounts.find(a=>a.email===email);if(register){if(existing){toast('Ya existe una cuenta local con este correo');return}const account={name:String(form.get('name')).trim(),email,passwordHash,role:'customer',createdAt:new Date().toISOString()};accounts.push(account);localStorage.setItem(LOCAL_AUTH_KEY,JSON.stringify(accounts));state.session={name:account.name,email:account.email,role:account.role};state.profile={...state.profile,name:account.name,email:account.email}}else{if(!existing||existing.passwordHash!==passwordHash){toast('Correo o contraseña local incorrectos');return}state.session={name:existing.name,email:existing.email,role:existing.role};state.profile={...state.profile,name:existing.name,email:existing.email}}save();closeDialog('auth');showAccount();toast('Sesión local iniciada correctamente')})}function showAccount(){if(!state.session){showAuth();return}if(!$('#accountDialog'))document.body.insertAdjacentHTML('beforeend','<dialog id="accountDialog" class="dialog account-dialog"><button class="close" data-close="account">×</button><div id="accountContent"></div></dialog>');const orders=state.orders.length?state.orders.map(o=>`<article class="order-item"><b>${o.id}</b><span>${o.status}</span><small>${o.date} · ${o.tracking}</small><strong>${money(o.total)}</strong></article>`).join(''):'<p class="muted-copy">Aún no tienes pedidos demo.</p>';$('#accountContent').innerHTML=`<div class="account-content"><p class="eyebrow">CUENTA LOCAL · ${state.session.role==='admin'?'ADMINISTRADOR':'CLIENTE'}</p><h2>Hola, ${state.session.name}</h2><div class="account-grid"><form id="profileForm" class="checkout-form"><label>Nombre<input name="name" value="${state.profile.name||state.session.name}" required></label><label>Correo<input name="email" type="email" value="${state.profile.email||state.session.email}" required></label><label>Dirección principal<input name="address" value="${state.profile.address||''}"></label><button class="button button-green">Guardar perfil</button><button type="button" id="logoutButton" class="text-button">Cerrar sesión local</button></form><div><h3>Pedidos y seguimiento</h3><div class="orders-list">${orders}</div>${state.session.role==='admin'?'<button id="openAdmin" class="text-button">Abrir panel administrador →</button>':''}</div></div></div>`;$('#accountDialog').showModal();$('#profileForm').addEventListener('submit',e=>{e.preventDefault();state.profile=Object.fromEntries(new FormData(e.currentTarget));save();toast('Perfil local guardado')});$('#logoutButton').addEventListener('click',()=>{state.session=null;save();closeDialog('account');toast('Sesión local cerrada')});$('#openAdmin')?.addEventListener('click',showAdmin)}
